// Small street details: benches, bins, and a welcoming town sign
const benchWood=mat('#a77b51'), binMat=mat('#55716a');for(const [x,z,r] of [[-5,-8,0],[5,8,Math.PI],[-17,0,Math.PI/2],[17,0,-Math.PI/2]]){const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=r;scene.add(g);box(g,0,.58,0,1.35,.13,.42,benchWood);for(const xx of [-.5,.5]){box(g,xx,.32,0,.1,.52,.1,lampMat);box(g,xx,.78,-.19,.1,.42,.09,benchWood)}box(g,1.15,.42,.15,.45,.82,.45,binMat);cyl(g,1.15,.85,.15,.24,.24,.05,lampMat,12)}
const signG=new THREE.Group();signG.position.set(-2.2,0,-8);scene.add(signG);cyl(signG,0,.8,0,.08,.08,1.6,trunkMat,8);box(signG,0,1.63,0,2.1,.72,.16,mat('#314a40'));box(signG,0,1.63,.1,1.92,.54,.04,mat('#d7ed9b')); // sign face accent
// physics objects
const bodies=[];const definitions={crate:{label:'Wood crate',radius:.69,mass:1.55,bounce:.34,color:'#c58b53'},ball:{label:'Super ball',radius:.61,mass:.55,bounce:.84,color:'#ee765a'},barrel:{label:'Oil drum',radius:.62,mass:1.25,bounce:.28,color:'#587f7d'},rock:{label:'Big rock',radius:.78,mass:2.5,bounce:.18,color:'#777d73'}};
let selected='crate',gravityOn=true,paused=false,power=1,impact=0,lastImpactAt=0;
function makeBody(kind,position,velocity=new THREE.Vector3()){const d=definitions[kind];let mesh;if(kind==='crate'){mesh=new THREE.Mesh(new THREE.BoxGeometry(1.16,1.16,1.16),mat(d.color,.9));const edge=new THREE.EdgesGeometry(mesh.geometry);const lines=new THREE.LineSegments(edge,new THREE.LineBasicMaterial({color:'#815936',transparent:true,opacity:.65}));mesh.add(lines);}
else if(kind==='ball'){mesh=new THREE.Mesh(new THREE.SphereGeometry(d.radius,20,14),new THREE.MeshStandardMaterial({color:d.color,roughness:.25,metalness:.02}));const stripe=new THREE.Mesh(new THREE.TorusGeometry(d.radius*.72,.035,6,36),mat('#fff1d2',.4));stripe.rotation.x=Math.PI/2;mesh.add(stripe);const stripe2=stripe.clone();stripe2.rotation.y=Math.PI/2;mesh.add(stripe2);}
else if(kind==='barrel'){mesh=new THREE.Mesh(new THREE.CylinderGeometry(.52,.52,1.3,16),new THREE.MeshStandardMaterial({color:d.color,roughness:.47,metalness:.26}));for(const y of [-.38,.38]){const hoop=new THREE.Mesh(new THREE.TorusGeometry(.525,.045,6,16),mat('#bcc4b3',.35,.5));hoop.rotation.x=Math.PI/2;hoop.position.y=y;mesh.add(hoop)}}
else{mesh=new THREE.Mesh(new THREE.DodecahedronGeometry(.68,1),mat(d.color,1));mesh.scale.set(1.12,.92,1);}
mesh.castShadow=true;mesh.receiveShadow=true;mesh.position.copy(position);scene.add(mesh);const body={kind,mesh,pos:position.clone(),vel:velocity.clone(),rotVel:new THREE.Vector3((Math.random()-.5)*1.5,(Math.random()-.5)*1.5,(Math.random()-.5)*1.5),radius:d.radius,mass:d.mass,bounce:d.bounce,sleep:0};bodies.push(body);if(bodies.length>40){const old=bodies.shift();scene.remove(old.mesh);old.mesh.geometry.dispose()}updateCount();return body}
function updateCount(){document.querySelector('#objectCount').textContent=bodies.length}
function clampTown(body){const r=body.radius;for(const c of staticColliders){const dx=body.pos.x-c.x,dz=body.pos.z-c.z,px=c.rx+r-Math.abs(dx),pz=c.rz+r-Math.abs(dz);if(px>0&&pz>0&&body.pos.y-r<c.top&&body.pos.y+r>.08){if(px<pz){body.pos.x+=(dx>=0?px:-px);if((dx>=0?body.vel.x:-body.vel.x)<0)body.vel.x=-(body.vel.x)*.55}else{body.pos.z+=(dz>=0?pz:-pz);if((dz>=0?body.vel.z:-body.vel.z)<0)body.vel.z=-(body.vel.z)*.55}body.vel.multiplyScalar(.94);body.sleep=0}}
// tree trunks and lamp bases are satisfying little bumpers
for(const [x,z] of [...treePositions,...[[-5,-5],[5,-5],[-5,5],[5,5],[-20,0],[20,0],[0,-18],[0,18]]]){const dx=body.pos.x-x,dz=body.pos.z-z,dist=Math.hypot(dx,dz),min=r+.31;if(dist<min&&body.pos.y<2.1){const nx=(dx||.001)/dist,nz=(dz||.001)/dist;body.pos.x=x+nx*min;body.pos.z=z+nz*min;const vn=body.vel.x*nx+body.vel.z*nz;if(vn<0){body.vel.x-=1.55*vn*nx;body.vel.z-=1.55*vn*nz}body.sleep=0}}
}
function physics(dt){const sub=2,step=dt/sub;for(let s=0;s<sub;s++){for(const b of bodies){if(b.sleep>1.3)continue;if(gravityOn)b.vel.y-=17*step;b.pos.addScaledVector(b.vel,step);b.mesh.rotation.x+=b.rotVel.x*step;b.mesh.rotation.y+=b.rotVel.y*step;b.mesh.rotation.z+=b.rotVel.z*step;
const floorY=b.radius;if(b.pos.y<floorY){b.pos.y=floorY;if(b.vel.y<-.6){const speed=Math.abs(b.vel.y);if(speed>4&&performance.now()-lastImpactAt>220){impact=Math.max(impact,Math.round(speed*3.6));lastImpactAt=performance.now()}b.vel.y=-b.vel.y*b.bounce;b.vel.x*=.82;b.vel.z*=.82;b.rotVel.x+=b.vel.z*.06;b.rotVel.z-=b.vel.x*.06;if(Math.abs(b.vel.y)<1.05)b.vel.y=0}else b.vel.y=0;b.vel.x*=Math.pow(.86,step*60);b.vel.z*=Math.pow(.86,step*60);b.rotVel.multiplyScalar(.97)}
if(Math.abs(b.pos.x)>25){b.pos.x=Math.sign(b.pos.x)*25;b.vel.x*=-.6}if(Math.abs(b.pos.z)>23){b.pos.z=Math.sign(b.pos.z)*23;b.vel.z*=-.6}clampTown(b);b.vel.multiplyScalar(Math.pow(.997,step*60));if(b.vel.length()<.09&&b.pos.y<=floorY+.015)b.sleep+=step;else b.sleep=0;b.mesh.position.copy(b.pos)}
// Dynamic object collisions: lightweight sphere contacts and impulse transfer.
for(let i=0;i<bodies.length;i++)for(let j=i+1;j<bodies.length;j++){const a=bodies[i],b=bodies[j],dx=b.pos.x-a.pos.x,dy=b.pos.y-a.pos.y,dz=b.pos.z-a.pos.z,d=Math.hypot(dx,dy,dz),min=a.radius+b.radius;if(d<min&&d>.001){const nx=dx/d,ny=dy/d,nz=dz/d,over=min-d;a.pos.x-=nx*over*.5;a.pos.y-=ny*over*.5;a.pos.z-=nz*over*.5;b.pos.x+=nx*over*.5;b.pos.y+=ny*over*.5;b.pos.z+=nz*over*.5;const rel=(b.vel.x-a.vel.x)*nx+(b.vel.y-a.vel.y)*ny+(b.vel.z-a.vel.z)*nz;if(rel<0){const jimp=-(1+Math.min(a.bounce,b.bounce))*rel/(1/a.mass+1/b.mass);a.vel.x-=jimp*nx/a.mass;a.vel.y-=jimp*ny/a.mass;a.vel.z-=jimp*nz/a.mass;b.vel.x+=jimp*nx/b.mass;b.vel.y+=jimp*ny/b.mass;b.vel.z+=jimp*nz/b.mass;if(Math.abs(rel)>4){impact=Math.max(impact,Math.round(Math.abs(rel)*3.6));lastImpactAt=performance.now()}}a.sleep=b.sleep=0}}
}}
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);function groundAt(clientX,clientY){pointer.set(clientX/innerWidth*2-1,-clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);const p=new THREE.Vector3();return raycaster.ray.intersectPlane(groundPlane,p)?p:null}
let press=null,dragged=false,orbiting=false,lastPointer=null;const pointers=new Map();let orbitTouch=false;
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size>1){orbitTouch=true;press=null;lastPointer={x:e.clientX,y:e.clientY};return}if(e.button===2||e.button===1){orbiting=true;lastPointer={x:e.clientX,y:e.clientY};return}const p=groundAt(e.clientX,e.clientY);if(p){press={p,screen:{x:e.clientX,y:e.clientY},id:e.pointerId};dragged=false}});
canvas.addEventListener('pointermove',e=>{if(pointers.has(e.pointerId))pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(orbiting||orbitTouch){if(lastPointer){const dx=e.clientX-lastPointer.x,dy=e.clientY-lastPointer.y;azimuth-=dx*.006;polar=THREE.MathUtils.clamp(polar+dy*.004,.42,1.36);updateCamera()}lastPointer={x:e.clientX,y:e.clientY};return}if(press&&press.id===e.pointerId&&Math.hypot(e.clientX-press.screen.x,e.clientY-press.screen.y)>8)dragged=true});
canvas.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);if(orbitTouch){if(pointers.size<2){orbitTouch=false;lastPointer=null}return}if(orbiting){orbiting=false;lastPointer=null;return}if(press&&press.id===e.pointerId){const start=press.p,end=groundAt(e.clientX,e.clientY)||start;const delta=new THREE.Vector3(end.x-start.x,0,end.z-start.z);let vel=new THREE.Vector3();if(dragged){const len=delta.length();if(len>.05){delta.normalize();const speed=THREE.MathUtils.clamp(len*1.35,4,19)*power;vel.set(delta.x*speed,Math.min(7+Math.abs(e.clientY-press.screen.y)*.055,12)*power,delta.z*speed)}}else{const forward=new THREE.Vector3();camera.getWorldDirection(forward);forward.y=0;forward.normalize();vel.set(forward.x*2.7*power,5.6*power,forward.z*2.7*power)}const startY=definitions[selected].radius+(dragged?.08:2.7);makeBody(selected,new THREE.Vector3(start.x,startY,start.z),vel);if(dragged)showToast(`${definitions[selected].label} launched!`);else showToast(`${definitions[selected].label} dropped in`);press=null}});
canvas.addEventListener('pointercancel',()=>{press=null;orbiting=false;orbitTouch=false;pointers.clear()});canvas.addEventListener('wheel',e=>{radius=THREE.MathUtils.clamp(radius+e.deltaY*.025,21,65);updateCamera()},{passive:true});
function showToast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),1150)}
const toolButtons=[...document.querySelectorAll('.tool')];function selectKind(k){selected=k;toolButtons.forEach(b=>b.classList.toggle('active',b.dataset.kind===k));showToast(`${definitions[k].label} selected`)}toolButtons.forEach(b=>b.addEventListener('click',()=>selectKind(b.dataset.kind)));
document.querySelector('#power').addEventListener('input',e=>{power=Number(e.target.value)/100;document.querySelector('#powerLabel').textContent=`${e.target.value}%`});document.querySelector('#gravityBtn').addEventListener('click',e=>{gravityOn=!gravityOn;e.currentTarget.classList.toggle('off',!gravityOn);showToast(gravityOn?'Gravity on':'Zero gravity')});
function togglePause(){paused=!paused;document.querySelector('#playText').textContent=paused?'SIMULATION PAUSED':'SIMULATION LIVE';document.querySelector('.live-dot').style.background=paused?'#e4a95c':'#66bb84';showToast(paused?'Simulation paused':'Simulation resumed')}
document.querySelector('#playBtn').addEventListener('click',togglePause);function reset(){for(const b of bodies)scene.remove(b.mesh);bodies.length=0;impact=0;paused=false;document.querySelector('#playText').textContent='SIMULATION LIVE';document.querySelector('.live-dot').style.background='#66bb84';updateCount();showToast('Town cleared — start throwing!')}
document.querySelector('#resetBtn').addEventListener('click',reset);document.querySelector('#zoomIn').addEventListener('click',()=>{radius=Math.max(21,radius-3);updateCamera()});document.querySelector('#zoomOut').addEventListener('click',()=>{radius=Math.min(65,radius+3);updateCamera()});document.querySelector('#homeView').addEventListener('click',()=>{target.set(0,0,0);radius=40;azimuth=Math.PI*.25;polar=1.02;updateCamera()});window.addEventListener('keydown',e=>{if(['INPUT','BUTTON'].includes(document.activeElement.tagName))return;if(e.key>='1'&&e.key<='4')selectKind(['crate','ball','barrel','rock'][Number(e.key)-1]);if(e.code==='Space'){e.preventDefault();togglePause()}if(e.key.toLowerCase()==='r')reset()});
let prev=performance.now(),elapsed=0;function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-prev)/1000);prev=now;if(!paused){physics(dt);elapsed+=dt}if(now-lastImpactAt>1700)impact=Math.max(0,impact-dt*20);document.querySelector('#impactValue').textContent=Math.round(impact);const minutes=Math.floor((9*60+41+elapsed*.45)%720),hh=String(Math.floor(minutes/60)).padStart(2,'0'),mm=String(minutes%60).padStart(2,'0');document.querySelector('#clock').textContent=`${hh}:${mm}`;renderer.render(scene,camera)}requestAnimationFrame(animate);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2))});
</script></body></html>

