+const treePositions = [[-15, -6], [-7, -6], [7, -6], [15, -6], [-15, 6], [-7, 6], [7, 6], [15, 6], [-18, -13], [-5, -13], [5, -13], [18, -13], [-18, 13], [-5, 13], [5, 13], [18, 13]];
+for (let i = 0; i < treePositions.length; i++) {
+  const [x, z] = treePositions[i];
+  const g = new THREE.Group();
+  g.position.set(x, 0, z);
+  scene.add(g);
+  cyl(g, 0, 0.78, 0, 0.24, 0.31, 1.55, trunkMat, 8);
+  const leaf = leafMats[i % leafMats.length];
+  const crown = sphere(g, 0, 2.05, 0, 0.95, leaf, 9);
